    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué elemento es indispensable para que exista lavado de activos?', 1, 'El lavado consiste en dar apariencia legítima a bienes de origen ilícito; sin una infracción precedente que los genere, no hay lavado. El monto o el sector no son requisitos del delito.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Que la operación supere US$15,000', false, 1), (v_q, 'Que los bienes provengan de una infracción precedente', true, 2), (v_q, 'Que participe una entidad financiera', false, 3), (v_q, 'Que el dinero salga del país', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Además de los delitos enumerados, ¿qué otra infracción puede ser precedente del lavado según la Ley 155-17?', 1, 'La definición de infracción precedente incluye una cláusula general: toda infracción grave con pena no menor de tres años (art. 2, num. 11).', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Cualquier falta administrativa', false, 1), (v_q, 'Toda infracción grave sancionable con pena no menor de tres años', true, 2), (v_q, 'Solo los delitos cometidos en el extranjero', false, 3), (v_q, 'Únicamente el narcotráfico', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una red compra varios inmuebles a nombre de sociedades sin actividad y luego los revende entre ellas. ¿Qué etapa describe mejor esta conducta?', 1, 'Las compraventas sucesivas entre sociedades interpuestas crean capas que alejan los fondos de su origen: es la estratificación.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Colocación', false, 1), (v_q, 'Estratificación', true, 2), (v_q, 'Integración', false, 3), (v_q, 'Ninguna, es una operación inmobiliaria normal', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'El delito precedente se cometió en otro país y todavía no ha sido juzgado. ¿Puede perseguirse el lavado en la República Dominicana?', 1, 'El art. 6 establece que el lavado se investiga, enjuicia y falla como hecho autónomo, aunque el delito precedente se haya cometido en otra jurisdicción.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'No, primero debe haber condena por el delito precedente', false, 1), (v_q, 'Sí, porque el lavado es un delito autónomo, independiente de dónde se cometió el delito previo', true, 2), (v_q, 'Solo si el monto supera US$10,000', false, 3), (v_q, 'Solo si el autor es dominicano', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un empleado nota señales evidentes de que un cliente maneja dinero ilícito, pero decide «no preguntar para no saber». Según el art. 7, esta actitud:', 1, 'La ley declara equivalentes el conocimiento, el dolo, la obligación de conocer y la ignorancia deliberada.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Lo protege, porque no tenía conocimiento', false, 1), (v_q, 'Puede equipararse al conocimiento: la ley trata igual la ignorancia deliberada', true, 2), (v_q, 'Solo importa si el cliente es condenado', false, 3), (v_q, 'Es la conducta recomendada', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué pena prevé la ley para quien revela a un cliente que se envió un ROS sobre sus operaciones?', 1, 'El art. 4, num. 3 sanciona con 2 a 5 años de prisión mayor, multa e inhabilitación permanente a quien revela los ROS u otra información entregada a la UAF.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Ninguna, es una falta ética', false, 1), (v_q, 'Prisión de 2 a 5 años, multa e inhabilitación', true, 2), (v_q, 'Solo una amonestación interna', false, 3), (v_q, 'Una multa de US$100', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál es una diferencia clave entre el lavado de activos y el financiamiento del terrorismo?', 1, 'En el FT el dinero puede venir de fuentes lícitas; lo relevante es su destino y finalidad. En el lavado, el origen siempre es ilícito.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'El financiamiento del terrorismo siempre usa dinero ilícito', false, 1), (v_q, 'En el financiamiento del terrorismo los fondos pueden tener origen lícito y lo que se oculta es su destino', true, 2), (v_q, 'El lavado solo ocurre con montos pequeños', false, 3), (v_q, 'No existe diferencia práctica', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente coincide plenamente con una persona de la lista del Consejo de Seguridad de la ONU. ¿Qué corresponde?', 1, 'Los arts. 82 y 83 de la ley y el Decreto 407-17 exigen congelar sin demora, sin notificar a la persona afectada, y comunicar de inmediato la medida.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Avisarle para que aclare su situación', false, 1), (v_q, 'Congelar preventivamente sus bienes sin demora, sin notificarle, y comunicarlo al Ministerio Público y a la UAF', true, 2), (v_q, 'Esperar una orden judicial antes de actuar', false, 3), (v_q, 'Cerrar la cuenta y entregarle el saldo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué institución recibe y analiza los reportes de los sujetos obligados en la República Dominicana?', 1, 'La UAF es el ente técnico que recibe y analiza los reportes y eleva informes al Ministerio Público (art. 91).', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'El Ministerio Público', false, 1), (v_q, 'La Unidad de Análisis Financiero (UAF)', true, 2), (v_q, 'La Policía Nacional', false, 3), (v_q, 'El GAFI', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una joyería sin regulador específico es sujeto obligado. ¿Quién la supervisa en materia de prevención?', 1, 'El art. 2, num. 17 asigna a la DGII la supervisión de los sujetos obligados sin un organismo regulador estatal específico.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'La Superintendencia de Bancos', false, 1), (v_q, 'La Dirección General de Impuestos Internos (DGII)', true, 2), (v_q, 'La UAF', false, 3), (v_q, 'Nadie', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cajero nota que un cliente fracciona depósitos en efectivo. ¿Cuál es la actuación correcta?', 1, 'La primera línea documenta y escala por el canal interno. Revelar al cliente o a terceros que se analiza una operación está prohibido (art. 63).', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Preguntarle si está lavando dinero', false, 1), (v_q, 'Escalar internamente al oficial de cumplimiento, con los hechos, y guardar reserva', true, 2), (v_q, 'Ignorarlo porque cada depósito es pequeño', false, 3), (v_q, 'Comentarlo en el chat del equipo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un empleado reporta de buena fe y el cliente lo amenaza con demandarlo. Según el art. 58:', 1, 'El art. 58 exime de responsabilidad a quienes reportan a la UAF o informan a las autoridades en cumplimiento de la ley.', 12) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'El empleado responde civilmente', false, 1), (v_q, 'No incurre en responsabilidad civil, administrativa ni penal por reportar en cumplimiento de la ley', true, 2), (v_q, 'Debe retirar el reporte', false, 3), (v_q, 'Solo está protegido si el cliente es condenado', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué norma sustituyó la Ley 155-17?', 1, 'La Ley 155-17 derogó y sustituyó la Ley 72-02 sobre lavado de activos.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'La Ley 183-02', false, 1), (v_q, 'La Ley 72-02', true, 2), (v_q, 'La Ley 267-08', false, 3), (v_q, 'El Decreto 408-17', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un abogado que solo litiga en tribunales y nunca realiza para sus clientes las actividades del art. 33, lit. e, es:', 1, 'La DGII precisa que no son sujetos obligados los profesionales que no realicen al menos una de las actividades descritas.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Sujeto obligado no financiero en todo caso', false, 1), (v_q, 'No sujeto obligado, según la Norma 01-2018 de la DGII', true, 2), (v_q, 'Sujeto obligado financiero', false, 3), (v_q, 'Supervisor', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la Resolución CONCLAFIT-2025-02, una empresa constructora es sujeto obligado no financiero cuando:', 1, 'La resolución aclara que la condición depende de la actividad de riesgo concreta, no del objeto social.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Tiene más de 50 empleados', false, 1), (v_q, 'Interviene en compraventas de bienes raíces o promueve y pone en contacto a compradores y vendedores a cambio de comisión', true, 2), (v_q, 'Su objeto social menciona la construcción', false, 3), (v_q, 'Siempre, sin excepción', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál de estos NO es un componente mínimo del programa de cumplimiento del art. 34?', 1, 'El art. 34 exige políticas de riesgo, estándares de contratación y capacitación, régimen disciplinario, código de ética y auditoría externa.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Código de ética y buena conducta', false, 1), (v_q, 'Auditoría externa', false, 2), (v_q, 'Régimen de sanciones disciplinarias', false, 3), (v_q, 'Un seguro contra multas regulatorias', true, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Durante cuánto tiempo, como mínimo, deben conservarse los registros de debida diligencia y transacciones?', 1, 'El art. 43 exige conservar los registros al menos 10 años después de terminada la relación comercial o la transacción ocasional.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, '5 años', false, 1), (v_q, '10 años después de terminada la relación o la transacción', true, 2), (v_q, 'Mientras dure la relación', false, 3), (v_q, '2 años', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál es el plazo para remitir un Reporte de Operación Sospechosa a la UAF?', 1, 'El art. 55 fija 5 días hábiles contados desde que la operación fue realizada o intentada.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, '24 horas', false, 1), (v_q, '5 días hábiles después de realizada o intentada la operación', true, 2), (v_q, 'Los primeros 10 días del mes siguiente', false, 3), (v_q, '30 días calendario', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'La UAF solicita información sobre un cliente. Salvo que disponga un plazo menor, ¿en cuánto tiempo debe responder el sujeto obligado?', 1, 'El Decreto 408-17 (art. 25) establece un plazo no mayor de 10 días laborables, o menor si la UAF lo dispone.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, '48 horas', false, 1), (v_q, 'No más de 10 días laborables', true, 2), (v_q, '30 días', false, 3), (v_q, 'Cuando el cliente lo autorice', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la nota aclaratoria de la Resolución CONCLAFIT-2025-01, ¿cuál es el umbral de efectivo para premios, casinos, acciones y derechos de uso (literales d a g del art. 64)?', 1, 'La nota aclaratoria del 10 de diciembre de 2025 precisa que el monto correcto es RD$400,000.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'RD$250,000', false, 1), (v_q, 'RD$400,000', true, 2), (v_q, 'RD$450,000', false, 3), (v_q, 'RD$1,000,000', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Para registrar una compraventa sujeta al art. 64, ¿qué debe exigir el registrador según el reglamento?', 1, 'El Decreto 408-17 (art. 30) limita la responsabilidad del registrador a exigir la constancia del medio de pago.', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Una debida diligencia completa del comprador', false, 1), (v_q, 'Solo la constancia fehaciente del medio de pago', true, 2), (v_q, 'Prueba del origen de los fondos', false, 3), (v_q, 'Una carta de la UAF', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'No designar oficial de cumplimiento se clasifica como infracción:', 1, 'El art. 70 incluye entre las infracciones graves no designar oficial de cumplimiento.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Leve', false, 1), (v_q, 'Grave', true, 2), (v_q, 'Muy grave', false, 3), (v_q, 'No es infracción', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué rango de multa vigente aplica a una infracción muy grave de un sujeto obligado no financiero?', 1, 'Son los montos del art. 75, lit. a, actualizados por la Resolución CONCLAFIT-2024-01.', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'RD$300,000 a RD$1,000,000', false, 1), (v_q, 'RD$2,784,806 a RD$5,569,610', true, 2), (v_q, 'RD$6,962,014 a RD$13,924,025', false, 3), (v_q, 'RD$50,000 a RD$100,000', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿En cuánto tiempo prescribe una infracción administrativa muy grave?', 1, 'El art. 80 fija 5 años para las muy graves, 3 para las graves y 1 para las leves.', 12) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, '1 año', false, 1), (v_q, '3 años', false, 2), (v_q, '5 años', true, 3), (v_q, 'Nunca prescribe', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué describe mejor el enfoque basado en riesgos?', 1, 'El EBR adapta la intensidad de las medidas al riesgo identificado; es la Recomendación 1 del GAFI.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Aplicar los mismos controles a todos los clientes', false, 1), (v_q, 'Concentrar medidas más intensas donde el riesgo es mayor y más simples donde es menor', true, 2), (v_q, 'Eliminar todo cliente de riesgo', false, 3), (v_q, 'Revisar solo a los clientes nuevos', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la norma del sector seguros, el riesgo propio de la actividad, sin considerar los controles, es el riesgo:', 1, 'La norma define el riesgo inherente como el propio de la actividad sin tener en cuenta el efecto de los controles.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Residual', false, 1), (v_q, 'Inherente', true, 2), (v_q, 'Reputacional', false, 3), (v_q, 'Aceptado', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuáles son los cuatro factores mínimos de riesgo del art. 37 de la Ley 155-17?', 1, 'El art. 37 exige incorporar como mínimo clientes, productos o servicios, áreas geográficas y canales de distribución.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Clientes, productos y servicios, áreas geográficas y canales de distribución', true, 1), (v_q, 'Edad, sexo, nacionalidad y profesión', false, 2), (v_q, 'Monto, moneda, fecha y sucursal', false, 3), (v_q, 'Auditoría, cumplimiento, riesgo y legal', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué dos factores considera la ley, como mínimo, de alto riesgo (art. 46)?', 1, 'El art. 46 señala a las PEP y a las operaciones con jurisdicciones definidas por el GAFI.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Clientes nuevos y clientes jóvenes', false, 1), (v_q, 'Las PEP y las operaciones con jurisdicciones definidas por el GAFI', true, 2), (v_q, 'El efectivo y las tarjetas', false, 3), (v_q, 'Los empleados y los proveedores', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuándo NO es aceptable aplicar debida diligencia simplificada?', 1, 'El art. 42 establece que las medidas simplificadas no son aceptables cuando surgen sospechas o escenarios de riesgo mayor.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Cuando el cliente es una entidad estatal', false, 1), (v_q, 'Cuando surge una sospecha de lavado o financiamiento del terrorismo', true, 2), (v_q, 'Cuando el riesgo es bajo', false, 3), (v_q, 'Cuando el cliente es antiguo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En la norma de seguros, ¿qué etapa establece el perfil de riesgo residual de la entidad?', 1, 'Como resultado de la etapa de control y mitigación se establece el perfil de riesgo residual.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Identificación', false, 1), (v_q, 'Medición', false, 2), (v_q, 'Control y mitigación', true, 3), (v_q, 'Ninguna', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un sujeto obligado financiero lanza un producto nuevo. ¿Qué debe presentar?', 1, 'El párrafo del art. 45 exige presentar la evaluación de riesgos junto a un plan de mitigación.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Nada, solo si el supervisor lo pide', false, 1), (v_q, 'Una evaluación de riesgos y un plan de mitigación', true, 2), (v_q, 'Un ROS preventivo', false, 3), (v_q, 'Un seguro de responsabilidad', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la Norma 01-2018 de la DGII, ¿con qué frecuencia se actualiza la debida diligencia de los clientes habituales?', 1, 'La norma pide actualizar a los clientes habituales cada año y a los ocasionales cada dos años.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Cada mes', false, 1), (v_q, 'Cada año', true, 2), (v_q, 'Cada cinco años', false, 3), (v_q, 'Nunca', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En el mercado de valores, ¿cada cuánto debe revisarse como mínimo la matriz de riesgo?', 1, 'La norma del CNV exige revisarla al menos una vez al año y conservar la versión anterior.', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Una vez al año', true, 1), (v_q, 'Cada tres años', false, 2), (v_q, 'Solo al crearla', false, 3), (v_q, 'Cada diez años', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una entidad decide rechazar a todos los clientes de un sector económico sin evaluar casos individuales. Desde el EBR esto es:', 1, 'El EBR busca gestionar el riesgo con análisis; las exclusiones masivas sin evaluación no son lo que pide el estándar.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'La mejor práctica', false, 1), (v_q, 'Un error: el EBR pide evaluar y gestionar, no excluir por categoría sin análisis', true, 2), (v_q, 'Obligatorio por ley', false, 3), (v_q, 'Irrelevante', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente fue calificado de alto riesgo. ¿Qué corresponde?', 1, 'Riesgo alto implica diligencia ampliada (art. 42); el reporte procede solo si surge una sospecha tras el análisis.', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Enviar un ROS de inmediato', false, 1), (v_q, 'Aplicar debida diligencia ampliada y monitoreo reforzado', true, 2), (v_q, 'Cerrar la relación sin más', false, 3), (v_q, 'Nada, la calificación es informativa', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Para qué sirve principalmente la matriz de riesgo de clientes?', 1, 'La matriz clasifica a los clientes para aplicar una debida diligencia diferenciada.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Para calcular comisiones', false, 1), (v_q, 'Para asignar a cada cliente un nivel de riesgo que determina su debida diligencia y monitoreo', true, 2), (v_q, 'Para reemplazar la evaluación de la entidad', false, 3), (v_q, 'Para decidir qué reportar a la UAF sin análisis', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la Norma 01-2018 de la DGII, ¿en cuántos niveles como mínimo debe clasificar la matriz?', 1, 'La norma exige clasificar a los clientes como mínimo en bajo, medio y alto riesgo.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Dos: aceptado y rechazado', false, 1), (v_q, 'Tres: bajo, medio y alto', true, 2), (v_q, 'Cinco', false, 3), (v_q, 'No exige niveles', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En el mercado de valores, ¿quién elabora la matriz de riesgo?', 1, 'El art. 44 de la norma del CNV encarga al comité de cumplimiento elaborar la matriz.', 3) returning id into v_q;
