    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál de estos datos NO figura entre los requisitos mínimos de la matriz del mercado de valores?', 1, 'La norma pide datos del cliente, productos, duración, calificación y tipo de debida diligencia, entre otros; no datos como la religión.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Productos utilizados', false, 1), (v_q, 'Duración de la relación comercial', false, 2), (v_q, 'Tipo de debida diligencia a aplicar', false, 3), (v_q, 'La religión del cliente', true, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En el ejemplo resuelto, ¿por qué el primer cliente resultó de riesgo alto?', 1, 'El nivel se obtiene comparando el puntaje ponderado con los rangos definidos en la política.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Porque usa el canal presencial', false, 1), (v_q, 'Porque su puntaje ponderado (3.35) superó el umbral definido para alto (3.21)', true, 2), (v_q, 'Porque es persona jurídica', false, 3), (v_q, 'Porque todos los clientes con cuenta corriente son de alto riesgo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente obtiene puntaje bajo, pero es PEP. ¿Qué nivel le corresponde?', 1, 'La ley considera a las PEP factor de alto riesgo; la matriz debe incorporar esa regla.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Bajo, porque manda el puntaje', false, 1), (v_q, 'Alto, por la regla de prevalencia que refleja el art. 46', true, 2), (v_q, 'Medio, como promedio', false, 3), (v_q, 'No se califica', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una coincidencia confirmada con las listas del Consejo de Seguridad de la ONU debería:', 1, 'Los arts. 82 y 83 de la ley obligan a congelar sin demora y comunicar la coincidencia.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Sumar un punto al puntaje', false, 1), (v_q, 'Activar el procedimiento de congelamiento sin demora', true, 2), (v_q, 'Ignorarse si el cliente es antiguo', false, 3), (v_q, 'Esperar a la revisión anual', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué aporta la segmentación al monitoreo?', 1, 'Comparar a un cliente con sus pares permite identificar comportamientos fuera de lo normal.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Permite definir lo esperado en grupos similares y detectar desviaciones', true, 1), (v_q, 'Reemplaza la debida diligencia', false, 2), (v_q, 'Sirve solo para mercadeo', false, 3), (v_q, 'Elimina las alertas', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En el mercado de valores, al modificar la matriz se debe:', 1, 'El art. 44 exige consignar la modificación y su finalidad y conservar siempre la matriz anterior.', 9) returning id into v_q;
