    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Para una persona jurídica, ¿qué exige entender el art. 40 de la ley?', 1, 'El art. 40 incluye razón social, identificación tributaria, forma jurídica, estructura de propiedad y control, dirección y beneficiario final.', 5) returning id into v_q;
