    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'No, la afinidad no cuenta', false, 1), (v_q, 'Sí, es pariente por afinidad en segundo grado', true, 2), (v_q, 'Solo si vive con el ministro', false, 3), (v_q, 'Solo si es funcionario', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué medidas exige el art. 18 del Decreto 408-17 para una PEP?', 1, 'Son las tres actuaciones del art. 18.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Cobrarle comisiones más altas', false, 1), (v_q, 'Aprobación de la alta gerencia, origen de los fondos y monitoreo intensificado', true, 2), (v_q, 'Reportarla a la UAF', false, 3), (v_q, 'Negarle el servicio', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente persona jurídica tiene como beneficiario final a una PEP. ¿Aplica la debida diligencia ampliada?', 1, 'El art. 18 del Decreto 408-17 lo establece expresamente.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'No, la PEP no es el cliente', false, 1), (v_q, 'Sí, el reglamento la exige aun cuando la PEP sea beneficiaria final', true, 2), (v_q, 'Solo si la PEP es extranjera', false, 3), (v_q, 'Solo si lo pide la UAF', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En un seguro de vida, ¿hasta cuándo debe determinarse si el beneficiario es PEP?', 1, 'La norma de seguros lo exige a más tardar en el momento del pago.', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Nunca', false, 1), (v_q, 'A más tardar en el momento del pago', true, 2), (v_q, 'Solo al emitir la póliza', false, 3), (v_q, 'Cinco años después del pago', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente es identificado como PEP y su operativa es coherente con su perfil. ¿Procede un ROS?', 1, 'La UAF aclara que la condición de PEP no debe reportarse por sí misma.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Sí, siempre', false, 1), (v_q, 'No; se aplica diligencia ampliada, pero ser PEP no es motivo de reporte por sí solo', true, 2), (v_q, 'Sí, pero como RTE', false, 3), (v_q, 'Solo si es extranjero', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué diferencia hay entre fuente de riqueza y fuente de fondos?', 1, 'Ambas se indagan en la diligencia ampliada y responden preguntas distintas.', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Son lo mismo', false, 1), (v_q, 'La riqueza explica cómo se formó el patrimonio; los fondos, de dónde viene el dinero de una operación concreta', true, 2), (v_q, 'La riqueza solo aplica a empresas', false, 3), (v_q, 'Los fondos solo aplican a efectivo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente existente es nombrado viceministro. ¿Qué corresponde?', 1, 'El art. 18 exige aprobación para establecer o continuar la relación con una PEP.', 12) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Nada, ya era cliente', false, 1), (v_q, 'Obtener la aprobación de la alta gerencia para continuar la relación y aplicar diligencia ampliada', true, 2), (v_q, 'Cerrar la cuenta', false, 3), (v_q, 'Esperar tres años', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente deposita en efectivo US$9,000 por la mañana y US$7,000 por la tarde en la misma entidad, a su favor. ¿Qué corresponde según la ley?', 1, 'El art. 54 agrupa las transacciones múltiples en efectivo de una misma persona en 24 horas que, sumadas, alcanzan US$15,000.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Nada, ninguna supera el umbral', false, 1), (v_q, 'Agruparlas como una sola transacción y reportarla en el RTE', true, 2), (v_q, 'Solo un RAS', false, 3), (v_q, 'Esperar al día siguiente', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál es el umbral del RTE para los casinos?', 1, 'El párrafo del art. 52 fija US$3,000 para los casinos.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'US$15,000', false, 1), (v_q, 'US$10,000', false, 2), (v_q, 'US$3,000', true, 3), (v_q, 'No reportan RTE', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuándo deben remitirse los RTE a la UAF?', 1, 'El art. 53 establece la remisión dentro de los primeros diez días calendario del mes siguiente.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Dentro de 5 días hábiles', false, 1), (v_q, 'Los del mes anterior, dentro de los primeros 10 días calendario', true, 2), (v_q, 'Una vez al año', false, 3), (v_q, 'Solo cuando hay sospecha', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente intentó una operación sospechosa, pero desistió al pedírsele documentos. ¿Procede ROS?', 1, 'El art. 55 cuenta el plazo desde que la operación fue realizada o intentada.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'No, porque no se concretó', false, 1), (v_q, 'Sí, el ROS abarca operaciones realizadas o intentadas', true, 2), (v_q, 'Solo si superó US$15,000', false, 3), (v_q, 'Solo un RAS', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál afirmación sobre el ROS es correcta?', 1, 'La UAF aclara que no se requiere certeza ni identificar el tipo penal, pero sí analizar antes de reportar.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Hay que probar el delito antes de reportar', false, 1), (v_q, 'No se requiere certeza del delito, pero sí un análisis previo que sustente la sospecha', true, 2), (v_q, 'Solo se reportan montos altos', false, 3), (v_q, 'Es una denuncia penal', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué pregunta de las 5W suele faltar en los reportes débiles?', 1, 'Sin el «por qué» el reporte no explica la sospecha; es uno de los errores que señala la UAF.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, '¿Dónde?', false, 1), (v_q, '¿Por qué? (las razones concretas de la sospecha)', true, 2), (v_q, '¿Cuándo?', false, 3), (v_q, 'Ninguna', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente aparece en una noticia de hace diez años por un delito ya juzgado y no tiene operaciones inusuales. ¿Qué reporte corresponde?', 1, 'Sin operación ni intento, una noticia negativa no genera ROS; puede valorarse un RAS.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'ROS obligatorio', false, 1), (v_q, 'No es un ROS; si se confirma un vínculo relevante, un RAS opcional', true, 2), (v_q, 'RTE', false, 3), (v_q, 'Ninguno nunca', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un potencial cliente se niega a entregar información para su identificación. ¿Qué exige la ley?', 1, 'El art. 62 ordena realizar un ROS cuando el potencial cliente se niega a aportar información para su identificación.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Un RAS', false, 1), (v_q, 'Un ROS', true, 2), (v_q, 'Nada si no abrió cuenta', false, 3), (v_q, 'Un RTE', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'El auditor externo pide la lista de ROS enviados para su revisión. Según la UAF y el art. 63:', 1, 'La UAF incluye a los auditores internos y externos dentro de «terceros».', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Se le entrega sin restricción', false, 1), (v_q, 'La prohibición de revelar alcanza también a auditores internos y externos', true, 2), (v_q, 'Solo si firma un acuerdo', false, 3), (v_q, 'Se le entrega una copia parcial', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En una remesa internacional, ¿qué error de goAML provoca rechazos con frecuencia?', 1, 'Es uno de los errores identificados por la UAF en reportes de transacciones internacionales.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Incluir el monto en moneda extranjera', false, 1), (v_q, 'Dejar vacíos los países de origen y destino o poner ambos como República Dominicana', true, 2), (v_q, 'Adjuntar documentos', false, 3), (v_q, 'Detallar la razón de la sospecha', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una cliente recibe decenas de pagos por ventas en redes sociales que nunca entrega, y el análisis confirma el patrón. Con el Código Penal vigente, ¿qué corresponde?', 1, 'Con la Ley 74-25 la estafa simple se sanciona con 3 a 5 años, por lo que alcanza el umbral de infracción precedente del art. 2, num. 11 de la Ley 155-17.', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Nada: la estafa simple no es delito precedente', false, 1), (v_q, 'Remitir un ROS, porque la estafa (art. 237, 3 a 5 años) es hoy delito precedente, y orientar a las víctimas a denunciar', true, 2), (v_q, 'Enviar solo un RTE', false, 3), (v_q, 'Esperar una sentencia condenatoria', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'La DGII pide un reporte estadístico mensual de ROS. ¿Qué debe contener?', 1, 'La Norma 01-2018 exige solo información estadística y cuantitativa, sin el contenido de los ROS.', 12) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'El relato completo de cada ROS', false, 1), (v_q, 'Cantidad, montos, oficinas y fechas, sin información sobre el contenido', true, 2), (v_q, 'Los nombres de los clientes reportados', false, 3), (v_q, 'Copia de goAML', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué es una señal de alerta?', 1, 'La señal de alerta activa el análisis previo; no es una conclusión.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Una prueba de que el cliente cometió un delito', false, 1), (v_q, 'Un comportamiento o situación atípica que amerita un análisis más profundo', true, 2), (v_q, 'Una orden de la UAF', false, 3), (v_q, 'Un tipo de reporte', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la UAF, la inusualidad de una transacción:', 1, 'La guía de calidad señala que la inusualidad, aislada, puede no ser suficiente.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Siempre basta para reportar', false, 1), (v_q, 'Por sí sola puede no bastar y necesita complementarse con otros motivos de sospecha', true, 2), (v_q, 'Nunca es relevante', false, 3), (v_q, 'Solo importa en efectivo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál de estas es una señal del Anexo I de la norma de seguros?', 1, 'El Anexo I incluye la inusual despreocupación respecto de riesgos o costos.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Pagar la prima a tiempo', false, 1), (v_q, 'Inusual despreocupación por los riesgos o costos de las transacciones', true, 2), (v_q, 'Tener una sola póliza', false, 3), (v_q, 'Vivir en Santo Domingo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según la Norma 01-2018 de la DGII, ¿cuál puede considerarse operación sospechosa?', 1, 'Es uno de los supuestos del art. 38 de la Norma 01-2018.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Una compra coherente con el perfil', false, 1), (v_q, 'Operaciones a nombre de terceros que desconocen de las mismas', true, 2), (v_q, 'Pagar con transferencia', false, 3), (v_q, 'Pedir factura', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'En el Caso 2 (tienda de juguetes en diciembre), ¿por qué no se reporta?', 1, 'La estacionalidad documentada explica la variación; se archiva con nota y se mantiene el monitoreo.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Porque el monto es bajo', false, 1), (v_q, 'Porque existe una explicación documentada y coherente con su historia', true, 2), (v_q, 'Porque es una empresa', false, 3), (v_q, 'Porque diciembre está exento', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿En qué paso del método se busca una razón económica o legal para la operación?', 1, 'El tercer paso consiste en buscar y documentar una explicación razonable.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Contexto', false, 1), (v_q, 'Explicación', true, 2), (v_q, 'Geografía', false, 3), (v_q, 'Archivo', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente entrega como soporte una factura por un monto distinto al de la operación. Esto es:', 1, 'Las subguías incluyen como señal que el soporte corresponda a otra fuente o no coincida con el monto.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Irrelevante', false, 1), (v_q, 'Una señal de alerta recogida por la UAF en varios sectores', true, 2), (v_q, 'Un motivo de RTE', false, 3), (v_q, 'Prueba de lavado', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Tres sociedades nuevas comparten domicilio y apoderado sin razón económica. Según la norma de seguros, esto es:', 1, 'El Anexo I incluye el mismo domicilio o los mismos apoderados en distintas personas jurídicas sin razón económica.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Normal', false, 1), (v_q, 'Una señal de alerta', true, 2), (v_q, 'Un motivo de RTE', false, 3), (v_q, 'Una prueba de delito', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Por qué conviene documentar las alertas que se archivan?', 1, 'La documentación sustenta la decisión y mejora el sistema de alertas; además, los análisis se conservan 10 años.', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'No conviene', false, 1), (v_q, 'Porque demuestra el análisis, protege a la entidad y ayuda a calibrar las alertas', true, 2), (v_q, 'Para enviarlas al cliente', false, 3), (v_q, 'Para cobrar una comisión', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Durante el análisis de una alerta, ¿qué no se debe hacer?', 1, 'El art. 63 prohíbe revelar que se examina una operación.', 10) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Pedir soportes', false, 1), (v_q, 'Revelar al cliente que su operación está siendo examinada por sospecha', true, 2), (v_q, 'Revisar su perfil', false, 3), (v_q, 'Consultar al área de negocio', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un depósito alto aislado, con factura coherente, frente a un depósito alto de terceros sin vínculo, con soporte que no coincide y prisa por retirarlo:', 1, 'La combinación de señales de distintas categorías aumenta la probabilidad de que no exista una explicación legítima.', 11) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Son igual de sospechosos', false, 1), (v_q, 'El segundo combina señales de varias familias y merece mucho más análisis', true, 2), (v_q, 'Ninguno es relevante', false, 3), (v_q, 'El primero es más grave', false, 4);
    insert into public.exams (course_id, title, description, is_certification, status, time_limit_minutes, max_attempts, pass_percentage, shuffle_questions, is_free)
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Según el GAFI, ¿qué es un activo virtual?', 1, 'Es la definición del GAFI; excluye las representaciones digitales de moneda de curso legal.', 1) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Cualquier depósito bancario digital', false, 1), (v_q, 'Una representación digital de valor que puede comercializarse o transferirse digitalmente y usarse para pagos o inversiones', true, 2), (v_q, 'Una moneda de curso legal electrónica', false, 3), (v_q, 'Un bono del Estado', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál de estas actividades, realizada como negocio por cuenta de otros, convierte a alguien en PSAV?', 1, 'La custodia o administración de activos virtuales por cuenta de otros es una de las actividades de un PSAV.', 2) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Comprar bitcoin para uno mismo', false, 1), (v_q, 'Custodiar activos virtuales de clientes', true, 2), (v_q, 'Leer noticias sobre criptomonedas', false, 3), (v_q, 'Pagar con tarjeta', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Una billetera no custodiada es aquella en la que:', 1, 'En la billetera no custodiada el usuario controla sus claves.', 3) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Un banco controla las claves', false, 1), (v_q, 'El propio usuario controla sus claves sin intermediario', true, 2), (v_q, 'No se pueden recibir fondos', false, 3), (v_q, 'El Banco Central guarda los fondos', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál es la posición del Banco Central sobre las criptomonedas?', 1, 'El aviso de 2017, reiterado por la DGII, señala que no tienen curso legal ni respaldo.', 4) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Son moneda de curso legal', false, 1), (v_q, 'No son moneda de curso legal ni están respaldadas o autorizadas como medio de pago', true, 2), (v_q, 'Están prohibidas con pena de prisión', false, 3), (v_q, 'Son supervisadas por la UAF', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué artículo de la Ley 155-17 obliga a evaluar los riesgos de productos que usan nuevas tecnologías?', 1, 'El art. 45 exige identificar y evaluar esos riesgos y adoptar medidas para mitigarlos.', 5) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Art. 2', false, 1), (v_q, 'Art. 45', true, 2), (v_q, 'Art. 64', false, 3), (v_q, 'Art. 80', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué es la «regla de viaje»?', 1, 'Es la aplicación de la Recomendación 16 a las transferencias de activos virtuales.', 6) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Un límite para viajar con criptoactivos', false, 1), (v_q, 'La obligación de obtener, conservar y transmitir información del originador y del beneficiario en las transferencias de activos virtuales', true, 2), (v_q, 'Una tasa de cambio', false, 3), (v_q, 'Un tipo de billetera', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Cuál de estas es una señal de alerta del GAFI para activos virtuales?', 1, 'Los mezcladores y las monedas que refuerzan el anonimato figuran entre los indicadores del GAFI.', 7) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Mantener activos durante años', false, 1), (v_q, 'Usar servicios de mezcla para ocultar el rastro de los fondos', true, 2), (v_q, 'Comprar en una plataforma regulada con cuenta verificada', false, 3), (v_q, 'Declarar las ganancias', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'La presencia de un indicador de la guía del GAFI:', 1, 'La guía advierte que los indicadores deben analizarse en contexto.', 8) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Prueba un delito', false, 1), (v_q, 'Abre el análisis, pero no implica por sí sola actividad delictiva', true, 2), (v_q, 'Obliga a cerrar la cuenta', false, 3), (v_q, 'Se ignora', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente justifica sus depósitos como ganancias de criptoactivos, pero no aporta evidencia del capital inicial. ¿Qué corresponde?', 1, 'El origen de los fondos debe justificarse; la falta de soporte, sumada al perfil, puede llevar a un ROS.', 9) returning id into v_q;
    insert into public.answers (question_id, label, is_correct, position) values (v_q, 'Aceptar la explicación verbal', false, 1), (v_q, 'Solicitar soportes, actualizar la debida diligencia y evaluar un ROS si no se sustenta', true, 2), (v_q, 'Cerrar la cuenta sin análisis', false, 3), (v_q, 'Enviar un RTE', false, 4);
    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Que los criptoactivos no estén regulados específicamente en el país significa que:', 1, 'La falta de regulación específica no elimina el riesgo; el art. 45 y el enfoque basado en riesgos siguen aplicando.', 10) returning id into v_q;
