    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', '¿Qué ley dominicana tipifica la estafa cometida por medios electrónicos?', 1, 'El art. 15 de la Ley 53-07 sanciona la estafa realizada por medios electrónicos.', 2) returning id into v_q;
