    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Con el Código Penal vigente (Ley 74-25), ¿cómo se trata la estafa en materia de lavado de activos?', 1, 'La estafa simple (art. 237) se castiga con 3 a 5 años; la Ley 155-17 considera precedente toda infracción grave con pena no menor de tres años.', 3) returning id into v_q;
