    insert into public.questions (exam_id, type, prompt, points, explanation, position) values (v_x, 'single', 'Un cliente presenta un estado de cuenta falso para obtener un préstamo. ¿Cómo se analiza?', 1, 'Aislada, la falsedad privada no es precedente; usada para obtener un crédito, puede ser una estafa.', 8) returning id into v_q;
